use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdecltrait! {
# [doc = " Types implementing this trait can be parsed from a positional numeral system with radix 10. This"] # [doc = " trait allows for an additional sign character (`+` or `-`) in front of the actual number in"] # [doc = " order, to allow for parsing negative values."] pub trait FromRadix10Signed : Sized { # [doc = " Parses an integer from a slice."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use atoi::FromRadix10Signed;"] # [doc = " // Parsing to digits from a slice"] # [doc = " assert_eq!((42,2), i32::from_radix_10_signed(b\"42\"));"] # [doc = " // Additional bytes after the number are ignored"] # [doc = " assert_eq!((42,2), i32::from_radix_10_signed(b\"42 is the answer to life, the universe and everything\"));"] # [doc = " // (0,0) is returned if the slice does not start with a digit"] # [doc = " assert_eq!((0,0), i32::from_radix_10_signed(b\"Sadly we do not know the question\"));"] # [doc = " // Signs are allowed"] # [doc = " assert_eq!((-42,3), i32::from_radix_10_signed(b\"-42\"));"] # [doc = " // Signs are allowed"] # [doc = " assert_eq!((42,3), i32::from_radix_10_signed(b\"+42\"));"] # [doc = " // Even on unsigned types."] # [doc = " assert_eq!((0,2), u32::from_radix_10_signed(b\"-0\"));"] # [doc = " // Leading zeros are allowed"] # [doc = " assert_eq!((42,4), i32::from_radix_10_signed(b\"0042\"));"] # [doc = " ```"] # [doc = ""] # [doc = " # Return"] # [doc = ""] # [doc = " Returns a tuple with two numbers. The first is the integer parsed or zero, the second is the"] # [doc = " index of the byte right after the parsed number. If the second element is zero the slice"] # [doc = " did not start with an ASCII digit."] fn from_radix_10_signed (_ : & [u8]) -> (Self , usize) ; }
}